import type { KitComponentDefinition } from '../src/plugins/kit-component-definition';
import { kitComponentSchemas } from '../src/plugins/kit-component-schemas';
import { accessibilitySection } from './plugin-reference-accessibility';
import {
  componentDefinition,
  propsSchema,
  propsTable,
} from './plugin-reference-format';
import { resolvedReference } from './plugin-reference-inference';
import { slotTable } from './plugin-reference-slots';

const generatedNote =
  '<!-- Generated by packages/contracts/tools/generate-plugin-reference.mts. Do not edit by hand. -->';

function colorRule(name: string, component: KitComponentDefinition): string {
  return propsSchema(name).properties?.color
    ? resolvedReference(component).appearance
    : 'This schema does not declare a `color` prop; use the kit component’s documented semantic tokens.';
}

function imageRule(name: string, component: KitComponentDefinition): string {
  return name === 'Image'
    ? resolvedReference(component).appearance
    : 'This kit component does not declare a direct Image prop. Image Slots use the Image kit component’s source and appearance rules.';
}

function eventNote(name: string, event: string): string {
  const description = eventDescription(name, event);

  return `- \`${event}\`: ${description}`;
}

function eventPropertyDescription(
  name: string,
  event: string,
): string | undefined {
  const schema = propsSchema(name).properties?.[event];

  return typeof schema === 'object' ? schema.description : undefined;
}

function eventDescription(name: string, event: string): string {
  return (
    eventPropertyDescription(name, event) ??
    'Payload is defined by the event schema.'
  );
}

function eventNotes(name: string, component: KitComponentDefinition): string {
  const events = Object.keys(component.events);

  return events.length
    ? events.map((event) => eventNote(name, event)).join('\n')
    : 'This kit component defines no events.';
}

const code = (type: string): string => `\`${type}\``;

function childrenNote(component: KitComponentDefinition): string {
  if (component.children === true)
    return 'Accepts child kit components in source order.';

  if (!component.children) return 'Does not accept child nodes on the wire.';

  return `Accepts ${component.children.map(code).join(', ')} children in source order.`;
}

function sdkPropNote(component: KitComponentDefinition): string {
  const { sdkProps } = component.reference;

  return sdkProps ? `\n${sdkProps}` : '';
}

function appearanceSection(
  name: string,
  component: KitComponentDefinition,
): string {
  return [
    `- **Dark mode and color:** ${colorRule(name, component)}`,
    `- **Images:** ${imageRule(name, component)}`,
  ].join('\n');
}

function propsSection(name: string): string {
  return `## Props\n\n${propsTable(name).trimEnd()}`;
}

function slotsSection(name: string, component: KitComponentDefinition): string {
  const body = `${slotTable(name).trimEnd()}\n\n${childrenNote(component)}${sdkPropNote(component)}`;

  return `## Slots\n\n${body}`;
}

function componentSections(
  name: string,
  component: KitComponentDefinition,
): string[] {
  return [
    generatedNote,
    `# ${name}`,
    component.reference.summary,
    propsSection(name),
    slotsSection(name, component),
    `## Accessibility\n\n${accessibilitySection(name, component)}`,
    `## Appearance\n\n${appearanceSection(name, component)}`,
    `## Events\n\n${eventNotes(name, component)}`,
  ];
}

export function renderComponent(name: string): string {
  const component = componentDefinition(name);

  return `${componentSections(name, component).join('\n\n')}\n`;
}

export function renderIndex(names: string[]): string {
  const rows = names.map((name) => {
    const summary = componentDefinition(name).reference.summary;

    return `| [\`${name}\`](./${name}.md) | ${summary} |`;
  });

  return `${generatedNote}

# Plugin kit component reference

Generated from the kit component prop schemas and metadata in Contracts. Each page documents serialized props, accepted Slots, accessibility behavior, appearance, and events.

The reference catalog includes shipped kit components and Plugin-tier contracts recorded in the kit catalog. Pages are generated from Contracts schemas and metadata; they do not imply that a kit component is already available in every App version.

| Kit component | Summary |
| --- | --- |
${rows.join('\n')}
`;
}

export const documentedComponentNames = Object.keys(kitComponentSchemas).sort();
